<?php
require __DIR__ . '/includes/bootstrap.php';
$d = listing((int)get('id'));
if (!$d || (!is_public($d) && !can_manage($d))) abort_page(404, 'This listing is not available.');
$full = can_manage($d) || has_unlock((int)$d['id']);
if ((current_user()['role'] ?? '') === 'student') query('INSERT INTO recent_views (user_id,dormitory_id) VALUES (?,?) ON DUPLICATE KEY UPDATE viewed_at=CURRENT_TIMESTAMP', [current_user()['id'],$d['id']]);
$images = rows('SELECT id FROM dormitory_images WHERE dormitory_id=?' . ($full ? '' : ' AND is_public=1') . ' ORDER BY id', [$d['id']]);
$amenities = rows('SELECT a.name FROM amenities a JOIN dormitory_amenities da ON da.amenity_id=a.id WHERE da.dormitory_id=? ORDER BY a.id' . ($full ? '' : ' LIMIT 3'), [$d['id']]);
$title = $d['name']; require __DIR__ . '/includes/header.php';
?>
<section class="container section"><a class="back-link" href="<?= url('browse.php') ?>"><i class="bi bi-arrow-left" aria-hidden="true"></i> Back to all dorms</a><div class="section-heading"><div><span class="eyebrow"><?= $d['is_demo'] ? 'FICTIONAL DEMO LISTING' : 'FIND YOUR NEXT CHAPTER' ?></span><h1><?= e($d['name']) ?></h1><p><i class="bi bi-geo-alt" aria-hidden="true"></i> <?= e($d['location']) ?>, Cebu City · <?= e($d['university']) ?></p></div><span class="status-badge"><?= (int)$d['available_slots'] ? (int)$d['available_slots'] . ' slots available' : 'Fully Occupied' ?></span></div><?php if (!is_public($d)): ?><div class="alert alert-warning">Management preview · <?= e($d['status']) ?> · <?= $d['is_active'] ? 'Active' : 'Inactive' ?></div><?php endif; ?><div class="gallery"><?php foreach ($images as $i): ?><img src="<?= image_url((int)$i['id']) ?>" alt="<?= e($d['name']) ?> room photo<?= $d['is_demo'] ? ' (illustrative)' : '' ?>"><?php endforeach; ?></div><div class="details-grid"><div><section class="detail-section"><h2>A little about this place</h2><p><?= nl2br(e($d['description'])) ?></p><div class="detail-facts"><span><i class="bi bi-door-open" aria-hidden="true"></i><?= e($d['room_type']) ?></span><span><i class="bi bi-people" aria-hidden="true"></i><?= (int)$d['capacity'] ?>-person capacity</span><span><i class="bi bi-mortarboard" aria-hidden="true"></i><?= e($d['university']) ?></span></div></section><section class="detail-section"><h2><?= $full ? 'Amenities' : 'A peek at the amenities' ?></h2><div class="amenity-list"><?php foreach ($amenities as $a): ?><span><i class="bi bi-check2" aria-hidden="true"></i> <?= e($a['name']) ?></span><?php endforeach; ?></div></section>
<?php if ($full): ?><section class="detail-section"><span class="eyebrow">FULL DETAILS UNLOCKED</span><h2>The details that make a difference</h2><h3>Exact address</h3><p><?= e($d['exact_address']) ?></p><?php if ($d['map_url'] && preg_match('~^https://~i', $d['map_url'])): ?><a class="btn btn-outline-primary" target="_blank" rel="noopener noreferrer" href="<?= e($d['map_url']) ?>">Open map <i class="bi bi-box-arrow-up-right" aria-hidden="true"></i></a><?php endif; ?><h3>House rules</h3><p><?= nl2br(e($d['house_rules'])) ?></p><h3>Curfew</h3><p><?= e($d['curfew']) ?></p><h3>Security information</h3><p><?= nl2br(e($d['security_info'])) ?></p><p class="muted">Owner-provided information; independently confirm conditions before renting.</p><h3>Contact the owner</h3><p><?= e($d['owner_name']) ?><br><?= e($d['contact_number']) ?><br><?= e($d['owner_email']) ?></p><?php if ($d['is_demo']): ?><div class="alert alert-info">This address and contact information are fictional. No real property can be booked.</div><?php endif; ?></section><?php else: ?><section class="locked-panel"><i class="bi bi-lock" aria-hidden="true"></i><h2>Get the full picture.</h2><p>Unlock the exact address, owner contact, all photos, house rules, and complete amenities.</p><a class="btn btn-primary" href="<?= url('unlock.php?id=' . $d['id']) ?>">Unlock details · <?= money(scalar("SELECT setting_value FROM settings WHERE setting_key='unlock_fee'")) ?></a><small>One-time simulated payment per listing. No real money.</small></section><?php endif; ?></div><aside class="rent-panel"><span>Monthly rent</span><div class="big-price"><?= money($d['monthly_rent']) ?><small> / month</small></div><p><?= (int)$d['available_slots'] === 0 ? 'Fully occupied. No rooms currently available.' : e($d['available_slots']) . ' reported slots available' ?></p><hr><?php if (!$full): ?><a class="btn btn-primary w-100" href="<?= url('unlock.php?id=' . $d['id']) ?>">Unlock full details <i class="bi bi-key" aria-hidden="true"></i></a><?php else: ?><div class="alert alert-success">You have access to the full details.</div><?php endif; ?><button class="btn btn-outline-primary w-100 mt-3 compare-button" type="button" data-id="<?= $d['id'] ?>" aria-pressed="false">Add to comparison</button><p class="small mt-3">Unlocking gives access to information. It does not reserve a room.</p></aside></div></section>
<?php $related = rows(listing_select() . ' WHERE ' . public_condition() . ' AND d.id<>? AND (d.location=? OR d.university_id=?) ORDER BY d.id LIMIT 3',[$d['id'],$d['location'],$d['university_id']]); if ($related): ?><section class="container section"><h2>Another place to call home</h2><div class="cards-grid"><?php listing_cards($related); ?></div></section><?php endif; ?>
